const GARMENT_STUDIO_SETS=['suit','jacket','trousers','waistcoat','shirt','womens-suit'];
const GARMENT_READY_SETS=['trousers','waistcoat'];
const TROUSER_PART_KEYS=GARMENT_SETS.trousers.fields.map(f=>f[0]);
