const READY_SUMMARY_LABELS={jacket:'Jacket size',length:'Jacket length',trouser:'Trouser size',inseam:'Inseam',waistcoat:'Waistcoat size',womenSize:"Women's size",age:'Age'};
const READY_SUMMARY_ORDER=['jacket','length','trouser','womenSize','age','inseam','waistcoat'];
