function garmentMode(){const setId=garmentSetId();if(!GARMENT_STUDIO_SETS.includes(setId||''))return false;if(draft.method==='body')return true;if(draft.method==='garment')return !!GARMENT_MEASURE_SETS[setId];if(draft.method==='modify')return !!modifyBaseParts(setId,draft.wearer||'Men');if(draft.method!=='ready')return false;return (draft.wearer||'Men')!=='Men'||GARMENT_READY_SETS.includes(setId)}
