const MODIFY_BASE_SUMMARY_LABELS={jacket:'Jacket size',length:'Jacket length',trouser:'Trouser size',inseam:'Inseam',waistcoat:'Waistcoat size',womenSize:"Women's size",shirtSize:'Shirt size'};
