// the new size publishes nothing for it; a field the shopper has
// edited is never overwritten. draft.modifyPrefilled remembers
// which fields are still untouched guide values.
function applyModifyPrefill(){const setId=garmentSetId();if(!setId)return;const pre=modifyPrefillFor(setId,draft.base||{},draft.wearer||'Men');if(!draft.values)draft.values={};if(!Array.isArray(draft.modifyPrefilled))draft.modifyPrefilled=[];for(const k of Object.keys(pre)){if(draft.modifyPrefilled.includes(k)||draft.values[k]===undefined){draft.values[k]=pre[k];if(!draft.modifyPrefilled.includes(k))draft.modifyPrefilled.push(k)}}for(const k of [...draft.modifyPrefilled])if(!(k in pre)){delete draft.values[k];draft.modifyPrefilled=draft.modifyPrefilled.filter(x=>x!==k)}}
function updateModifyValue(key,v){updateValue(key,v);if(Array.isArray(draft.modifyPrefilled)&&draft.modifyPrefilled.includes(key)){draft.modifyPrefilled=draft.modifyPrefilled.filter(x=>x!==key);saveDraft()}}
function mmFieldHtml(def){const prefilled=Array.isArray(draft.modifyPrefilled)&&draft.modifyPrefilled.includes(def.key);return `<label class="field"><span class="guide-label">${def.label}<button type="button" class="help" aria-label="How to measure ${def.label.toLowerCase()}" onclick="gmShowGuide('${def.key}')">How to measure ↗</button></span><span class="subtle">Garment measurement${def.required?'':' · Optional'}${prefilled?' · Starting value from the size guide':''}</span><input id="measureInput-${def.key}" type="number" inputmode="decimal" step="0.1" aria-label="${def.label}" min="${Math.round(def.min*(draft.unit==='cm'?2.54:1))}" max="${Math.round(def.max*(draft.unit==='cm'?2.54:1))}" value="${displayValue(def.key)}" placeholder="${draft.unit==='cm'?'cm':'inches'}" onfocus="focusGarmentMeasureField('${def.key}')" oninput="updateModifyValue('${def.key}',this.value)"></label>`}
function modifyBaseSummary(profile){const base=(profile&&profile.base)||{};return MODIFY_BASE_SUMMARY_ORDER.filter(part=>base[part]!==undefined&&base[part]!==null&&base[part]!=='').map(part=>MODIFY_BASE_SUMMARY_LABELS[part]+' '+readyPartDisplay(part,base[part])).join(' · ')}
function modifyProfileReviewRows(x){const setId=setForGarment(x.profile.garment,x.profile.wearer||'Men'),defs=setId?modifyMeasureSetFields(setId):[],base=(x.profile&&x.profile.base)||{},unit=x.profile.unit==='cm'?'cm':'in';const baseRows=MODIFY_BASE_SUMMARY_ORDER.filter(part=>base[part]!==undefined&&base[part]!==null&&base[part]!=='').map(part=>`<div><span>${READY_PART_LABELS[part]||MODIFY_BASE_LABELS[part]||part}</span><strong>${esc(readyPartDisplay(part,base[part]))}</strong></div>`).join('');const valueRows=defs.filter(f=>Number.isFinite(x.profile.values&&x.profile.values[f.key])).map(f=>`<div><span>${f.label}</span><strong>${Math.round(x.profile.values[f.key]*(unit==='cm'?2.54:1)*10)/10} ${unit}</strong></div>`).join('');return baseRows+valueRows}
function readyPartFieldHtml(part){const r=draft.ready||{},v=r[part],label=READY_PART_LABELS[part];return `<label class="field">${label}<select aria-label="${label}" onchange="setGarmentReadyPart('${part}',this.value)"><option value="" ${v===undefined||v===null||v===''?'selected':''}>Choose ${READY_PART_SHORT_LABELS[part]}</option>${readyPartOptions(part).map(o=>`<option value="${o}" ${String(v)===String(o)?'selected':''}>${readyPartOptionLabel(part,o)}</option>`).join('')}</select></label>`}
function garmentFieldDef(setId,f){const range=fieldRange(f.key,draft.wearer||'Men');return{...f,min:range.min,max:range.max,kind:MEASUREMENT_FIELDS[f.key].kind,guidance:guidanceFor(setId,f.key)}}
function ensureDraftFits(){const set=GARMENT_SETS[garmentSetId()];if(!set)return;const fits={};for(const fit of set.fits)fits[fit.key]=draft.fits&&fit.options.includes(draft.fits[fit.key])?draft.fits[fit.key]:fit.default;draft.fits=fits}
function garmentFigure(id){const def=MEASUREMENT_FIELDS[id]||MEASUREMENT_FIELDS.chest;return figure('chest').replace('Illustration showing chest measurement','Illustration showing '+def.label.toLowerCase()+' measurement').replace('d="'+GARMENT_FIELD_LINES.chest+'"','d="'+(GARMENT_FIELD_LINES[id]||GARMENT_FIELD_LINES.chest)+'"')}
// Guidance images (package M9, owner decision O9): in the body
// measuring flow, the focused field's visual is a suits.me
// original photograph of a model with a red measuring tape at the
// field's placement, generated for this site in the instructional
// style the benchmark uses; the poses and tape placements follow
// the verified capture of 2026-10-29, and no benchmark image file
// was copied or traced. Diagram style fields get a per field line
// diagram drawn in the same hand as the M7 garment diagrams, with
// a dashed line and marked start and finish. The image resolves
// from the schema guidance ref by convention:
// assets/measure/<ref>.webp, with chest-women.webp the one variant.
// MEASURE_PHOTO_REFS lists exactly the refs a generated photo
// exists for on disk. The image generator refused four of the
// thirteen photographs (waist, seat, front-length and the women's
// chest variant), so those fields have no asset yet and keep the
// studio figure below; adding a produced ref to this list is the
// only change needed when its photo exists. A Boys wearer gets no
// photograph: the set was produced on adult models, so boys keep
// the figure for every field.
const MEASURE_PHOTO_REFS=['neck','chest','sleeve','shoulder','jacket-length','bicep','stomach','thigh','knee'];
function measurePhotoHtml(ref,def){return `<img class="measure-photo" src="assets/measure/${ref}.webp" alt="Photograph showing the tape placement for the ${def.label.toLowerCase()} measurement" loading="lazy">`}
// Per field line diagrams for the diagram style body fields,
// drawn on the studio figure in the M7 hand: a dashed red
// measurement line with a marked start and finish, of the kind
// the benchmark uses for length, rise and hem fields.
const BODY_DIAGRAM_OUTLINE='<circle cx="150" cy="41" r="28" fill="#d5cbbd"/><path d="M129 67v16l-51 14-31 139 25 6 31-105-9 98 5 40-6 155h34l23-152 23 152h34l-6-155 5-40-9-98 31 105 25-6-31-139-51-14V67" fill="#cec6b9" stroke="#938879" stroke-width="1.3"/><path d="M129 83l21 35 21-35M150 118v122M95 211h110M150 240v38" fill="none" stroke="#a29889" stroke-width="1"/>';
const BODY_DIAGRAMS={
height:{art:BODY_DIAGRAM_OUTLINE+'<path d="M274 22 L274 438 M60 438 L286 438" fill="none" stroke="#938879" stroke-width="1.3"/>',line:'M252 44 L252 434',from:[252,44],to:[252,434],fromLabel:[244,38,'end'],toLabel:[244,428,'end']},
'pants-length':{art:BODY_DIAGRAM_OUTLINE,line:'M206 210 L211 428',from:[206,210],to:[211,428],fromLabel:[214,204,'start'],toLabel:[219,432,'start']},
'front-rise':{art:BODY_DIAGRAM_OUTLINE,line:'M141 213 Q136 248 150 276',from:[141,213],to:[150,276],fromLabel:[133,206,'end'],toLabel:[158,283,'start']},
'back-rise':{art:BODY_DIAGRAM_OUTLINE,line:'M159 213 Q164 248 150 276',from:[159,213],to:[150,276],fromLabel:[167,206,'start'],toLabel:[142,283,'end']},
'leg-opening':{art:'<path d="M102 92 L124 402 L176 402 L198 92 Z" fill="#cec6b9" stroke="#938879" stroke-width="1.3"/><path d="M102 108 L198 108 M150 108 L149 402" fill="none" stroke="#a29889" stroke-width="1"/>',line:'M127 388 L173 388',from:[127,388],to:[173,388],fromLabel:[119,380,'end'],toLabel:[181,380,'start']},
'vest-length':{art:BODY_DIAGRAM_OUTLINE+'<path d="M114 86 L101 238 L150 264 L199 238 L186 86" fill="none" stroke="#a29889" stroke-width="1"/>',line:'M134 88 L134 256',from:[134,88],to:[134,256],fromLabel:[126,82,'end'],toLabel:[126,262,'end']}};
function bodyDiagramSvg(ref,def){const d=BODY_DIAGRAMS[ref];return `<svg viewBox="0 0 300 460" role="img" aria-label="Line diagram showing the ${def.label.toLowerCase()} measurement, from start to finish"><defs><pattern id="texture" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 5L5 0" stroke="#fff" stroke-width=".4" opacity=".5"/></pattern></defs>${d.art}<path d="${d.line}" fill="none" stroke="#c94b34" stroke-width="5" stroke-linecap="round" stroke-dasharray="10 7"/><circle cx="${d.from[0]}" cy="${d.from[1]}" r="5.5" fill="#c94b34"/><circle cx="${d.to[0]}" cy="${d.to[1]}" r="5.5" fill="#c94b34"/><text x="${d.fromLabel[0]}" y="${d.fromLabel[1]}" text-anchor="${d.fromLabel[2]}" font-family="Arial, sans-serif" font-size="12" letter-spacing="1" fill="#c94b34">START</text><text x="${d.toLabel[0]}" y="${d.toLabel[1]}" text-anchor="${d.toLabel[2]}" font-family="Arial, sans-serif" font-size="12" letter-spacing="1" fill="#c94b34">FINISH</text></svg>`}
// The visual for one body field in the body measuring flow: its
// photograph where one was produced, its line diagram for a
// diagram style field, and the studio figure everywhere else
// (fields without a produced photo, override refs for garments
// this site does not sell, and Boys wearers).
function bodyFieldVisual(key){const def=MEASUREMENT_FIELDS[key],g=guidanceFor(garmentSetId(),key),img=g?g.image:null,wearer=draft.wearer||'Men';if(img&&wearer!=='Boys'){if(img.style==='photo'){const ref=wearer==='Women'&&key==='chest'?'chest-women':img.ref;if(MEASURE_PHOTO_REFS.includes(ref))return measurePhotoHtml(ref,def)}if(img.style==='diagram'&&BODY_DIAGRAMS[img.ref])return bodyDiagramSvg(img.ref,def)}return garmentFigure(key)}
// Records the garment a measuring session is for, called by the
// product entry points. For suits and jackets it also prepares the
// in form fit selectors at their benchmark defaults (option
// selections, never measurements) and prefills the profile name the
// benchmark way, category and date, while the name is still the
// untouched default; the shopper can always rename it.
function noteGarmentContext(kind){draft.garment=kind||null;if(GARMENT_STUDIO_SETS.includes(garmentSetId()||'')){ensureDraftFits();if((draft.method==='body'||draft.method==='garment'||draft.method==='modify')&&(!draft.name||draft.name==='My measurements')){const now=new Date();draft.name=GARMENT_SETS[garmentSetId()].label+'_'+(now.getMonth()+1)+'/'+now.getDate()+'/'+now.getFullYear()}}saveDraft()}
// Legacy profile completion (J-M1c): a version 1 profile used for
// a garment is offered completion with exactly the fields it
// still owes, under its own wearer's rules (the offer extends to
// Women and Boys profiles in package M4). The offer lives in the
// customizer; the completion itself runs in this studio, seeded
// only with the values the migration carries, and writes nothing
