function missingFieldLabel(key,setId){if(key==='wearerName')return 'Name of the person being measured';if(key==='height')return 'Height';const set=setId?GARMENT_SETS[setId]:null,fit=set?set.fits.find(f=>f.key===key):null;if(fit)return fit.label;const def=MEASUREMENT_FIELDS[key];return def?def.label:key}
function completionPromptHtml(p){const prof=profiles.find(q=>q.id===config.profileId);if(!prof||prof.method!=='body')return'';const kind=p&&p.kind,setId=setForGarment(kind,prof.wearer||'Men');if(!GARMENT_STUDIO_SETS.includes(setId||''))return'';const missing=missingForCompletion(prof,kind);if(!missing||!missing.length)return'';return `<div class="note">This profile was saved with our previous measurements. For this ${garmentNounPlain(setId)} it still needs: ${missing.map(k=>esc(missingFieldLabel(k,setId))).join(', ')}. <button type="button" class="textlink" onclick="startProfileCompletion('${prof.id}')">Complete this profile</button></div>`}
function startProfileCompletion(id){const prof=profiles.find(q=>q.id===id);if(!prof)return;const kind=(products[config.product]||{}).kind;if(!GARMENT_STUDIO_SETS.includes(setForGarment(kind,prof.wearer||'Men')||''))return;draft.garment=kind;draft.method='body';draft.wearer=prof.wearer||'Men';draft.completionId=id;draft.completionMissing=missingForCompletion(prof,kind);const up=profileVersion(prof)===2?null:upgradeLegacyProfile(prof,kind);draft.values=up?{...up.profile.values}:{...(prof.values||{})};draft.wearerName=prof.wearerName||'';draft.fits=prof.fits?{...prof.fits}:null;ensureDraftFits();draft.name=prof.name||draft.name;draft.unit=prof.unit||'in';if(prof.fit)draft.fit=prof.fit;draft.step=0;returnToSuit=true;saveDraft();location.hash='#measure';render();toast('A few more measurements complete this profile.')}
function cancelCompletion(){draft.completionId=null;draft.completionMissing=null;draft.values={};draft.wearerName='';draft.fits=null;draft.step=0;saveDraft();stage=2;location.hash='#customize';render()}
function profileMeasureCount(p){if(p&&p.version===2&&p.values)return Object.keys(p.values).length;return fields.length}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function saveDraft(){write('suits-draft',draft)}function saveConfig(){write('suits-config',config)}
const readyFields=[['jacket','jacket size'],['length','jacket length'],['trouser','trouser size']];
function missingReady(){return readyFields.filter(([k])=>!draft.ready||!String(draft.ready[k]).trim()).map(x=>x[1])}
function cards(){let ps=products.map((p,i)=>({...p,id:i})).filter(p=>filter==='All suits'||p.fabric===filter||filter==='Wedding'&&p.id===3);if(sort==='low')ps.sort((a,b)=>a.price-b.price);if(sort==='high')ps.sort((a,b)=>b.price-a.price);return ps.map(p=>`<article class="product"><button onclick="chooseProduct(${p.id})" aria-label="Customize ${p.name}"><div class="product-photo"><img src="assets/${p.img}" alt="${p.name} suit" loading="lazy"><span class="badge">${p.tag}</span></div><h3>${p.name}</h3><div class="product-meta"><span>${p.fabric} · Made to measure</span><span>$${p.price}</span></div><div class="colors"><i style="--c:#28394d"></i><i style="--c:#5d5c59"></i><i style="--c:#b1a38b"></i><span class="subtle">+ customize</span></div></button></article>`).join('')||'<p>No suits match this selection.</p>'}
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">THE PERSONAL TAILORING EXPERIENCE</div><h1>Good taste.<br>Great fit.<br><em>Entirely you.</em></h1><p>Your fabric. Your details. Your measurements.<br>A suit that feels as individual as the person wearing it.</p><div class="hero-actions"><a class="btn orange" href="/collections/suits">Find your suit <span>↗</span></a><a class="textlink" href="/measure">Discover your fit →</a></div><div class="hero-note">CRAFTED FOR MEN, WOMEN & BOYS</div></div><div class="hero-image"><img src="assets/model-navy.webp" alt="Original AI-generated model wearing a navy tailored suit"><span class="image-caption">THE ART OF DRESSING LIKE YOURSELF.</span></div></section><div class="trust-strip"><span>INDIVIDUALLY MADE TO MEASURE</span><span>YOUR CHOICE, DOWN TO THE STITCH</span><span>EXPERTS IN PERSONAL TAILORING</span></div><section class="section"><div class="section-head"><div><div class="eyebrow">A WARDROBE, WELL CONSIDERED</div><h2>Find your signature.</h2></div><a class="textlink" href="/collections/suits">Explore the collection ↗</a></div><div class="products">${cards()}</div></section><section class="measurement-banner"><div class="copy"><div class="eyebrow">A BETTER FIT STARTS HERE</div><h2>Made to measure.<br>Made simple.</h2><p>No guesswork. Just a tape measure and a little guidance. Build your personal measurement profile, one clear step at a time.</p><a class="btn" href="/measure">Find my measurements <span>→</span></a><p class="subtle" style="margin-top:20px">Inches or centimeters · Save and return anytime</p></div><div class="measurement-art"><span class="art-tag">THE MEASUREMENT STUDIO</span>${figure('chest')}</div></section><section class="section" style="padding-top:20px"><div class="section-head"><div><div class="eyebrow">FROM AN IDEA TO YOUR IDEAL FIT</div><h2>A suit, your way.</h2></div></div><div class="steps"><article><b>01</b><h3>Find the fabric.</h3><p>Start with a color and a cloth that feel right for your everyday, or your biggest day.</p></article><article><b>02</b><h3>Make it personal.</h3><p>Choose the lapel, lining, and finishing touches that make the difference.</p></article><article><b>03</b><h3>Bring it into proportion.</h3><p>Follow our measurement guide, save your profile, and review every detail.</p></article></div></section><section class="craft" id="craft"><img src="assets/craftsmanship-BxSjRaOO.jpg" alt="A Suits.me tailor at work" loading="lazy"><div class="copy"><div class="eyebrow">THE HUMAN TOUCH</div><h2>Some things are<br>better made for you.</h2><p>A well-made suit begins with a conversation. From selecting your fabric to refining the fit, our approach puts you at the center of every decision.</p><a class="textlink" href="/locations">Meet us in a showroom ↗</a></div></section>`}
function collection(){return `<section class="collection-hero"><div class="copy"><div class="eyebrow">THE SUITS.ME COLLECTION</div><h1>Your next<br>signature piece.</h1><p>Start with a favorite. Make every detail your own.</p><span class="subtle">Preview collection · AI-generated model imagery</span></div><img src="assets/model-blue.webp" alt="Suits.me menswear collection"></section><section class="section"><div class="filter-row"><div class="filters">${['All suits','Wool','Linen','Wedding'].map(f=>`<button class="chip ${filter===f?'active':''}" onclick="setFilter('${f}')">${f}</button>`).join('')}</div><select aria-label="Sort suits" onchange="sort=this.value;render(false)"><option value="featured" ${sort==='featured'?'selected':''}>Featured</option><option value="low" ${sort==='low'?'selected':''}>Price: low to high</option><option value="high" ${sort==='high'?'selected':''}>Price: high to low</option></select></div><div class="products">${cards()}</div><p class="ai-note">Original AI-generated model photography · Illustrative garments and prices.</p></section>`}
function setFilter(f){filter=f;render(false)}function chooseProduct(i){editingBagId=null;config.product=i;config.fabric=products[i].color;saveConfig();stage=0;location.hash='#customize';if(location.hash==='#customize')render()}
function choice(key,values){return `<div class="choices">${values.map(v=>`<button class="choice ${config[key]===v?'active':''}" aria-pressed="${config[key]===v}" onclick="setOption('${key}','${v}')">${v}</button>`).join('')}</div>`}
function setOption(k,v){config[k]=v;if(k==='vest'&&v==='No vest')delete config.vestFabricBack;saveConfig();render(false)}
function pricedChoice(key,values,current,labels){current=current??config[key]??OPTION_DEFAULTS[key];return `<div class="choices">${values.map(v=>{const price=optionPrice(key,v);return `<button class="choice ${current===v?'active':''}" aria-pressed="${current===v}" onclick="setOption('${key}','${v}')">${labels?.[v]??v} · ${price?'+$'+price:'Included'}</button>`}).join('')}</div>`}
